styles:
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --font-li:     "STLiti", "SimLi", "LiSu", "隶书", serif;
  --font-kai:    "STKaiti", "KaiTi", "楷体", serif;
  --font-serif:  "Noto Serif SC", "Source Han Serif SC", serif;
  --font-mono:   "IBM Plex Mono", "Courier Prime", "Courier New", monospace;
}

html, body { margin: 0; width: 100%; height: 100%; overflow: hidden; background: #000; }

/* 摄像头占位背景 */
.v3x-video-bg {
  background:
    radial-gradient(ellipse at 30% 30%, rgba(120,80,40,0.55), transparent 55%),
    radial-gradient(ellipse at 70% 75%, rgba(70,45,35,0.55), transparent 55%),
    radial-gradient(ellipse at 50% 50%, rgba(40,30,22,0.65), transparent 70%),
    linear-gradient(180deg, #1a1410 0%, #0a0806 100%) !important;
}
.v3x-video-bg::after {
  content: ""; position: absolute; inset: 0;
  background-image: url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 200 260'><defs><radialGradient id='s' cx='50%25' cy='50%25' r='60%25'><stop offset='0%25' stop-color='%23d4a878'/><stop offset='100%25' stop-color='%235a3d28'/></radialGradient></defs><ellipse cx='100' cy='130' rx='70' ry='95' fill='url(%23s)'/><ellipse cx='80' cy='120' rx='5' ry='3' fill='%231a1a1a'/><ellipse cx='120' cy='120' rx='5' ry='3' fill='%231a1a1a'/><path d='M90 110 Q100 105 110 110' stroke='%233a2818' stroke-width='1.5' fill='none'/><path d='M85 155 Q100 165 115 155' stroke='%233a2818' stroke-width='1.5' fill='none'/><path d='M100 138 L96 165 L104 165 L100 170' stroke='%233a2818' stroke-width='1.5' fill='none'/></svg>");
  background-repeat: no-repeat; background-position: center 45%;
  background-size: 380px 480px; opacity: 0.78;
}

/* 暗化遮罩（仅中央收紧光圈） */
.v3x-dim-overlay {
  position: fixed; inset: 0;
  background: radial-gradient(ellipse at 50% 38%, transparent 20%, rgba(0,0,0,0.55) 80%);
  pointer-events: none; z-index: 4;
}

/* 检测框（默认被金 · fork 时更明显） */
.v3x-frame { border: none !important; }
.v3x-frame .v3x-corner {
  width: 90px !important; height: 90px !important;
  border-color: #f5d400 !important; border-width: 6px !important;
  box-shadow: 0 0 30px rgba(245,212,0,0.4);
}
.v3x-frame-label {
  position: absolute; top: -26px; left: 0;
  font-family: 'Courier New', monospace;
  font-size: 14px; font-weight: 900; color: #f5d400;
  text-transform: uppercase; letter-spacing: 3px;
  display: flex; align-items: center; gap: 8px;
  background: rgba(0,0,0,0.7); padding: 4px 10px;
  border: 1.5px solid #f5d400;
}
.v3x-frame-label .dot {
  display: inline-block; width: 8px; height: 8px;
  background: #f5d400; box-shadow: 0 0 6px #f5d400;
  animation: v3xDotPulse 1.2s ease-in-out infinite;
}
@keyframes v3xDotPulse {
  0%, 100% { opacity: 1; }
  50% { opacity: 0.4; }
}
body.forked .v3x-frame .v3x-corner {
  box-shadow: 0 0 40px rgba(245,212,0,0.7);
  animation: v3xCornerBreath 1.4s ease-in-out infinite;
}
@keyframes v3xCornerBreath {
  0%, 100% { transform: scale(1); }
  50% { transform: scale(1.06); }
}
body.forked .v3x-frame .v3x-scanline {
  background: linear-gradient(90deg, transparent, rgba(245,212,0,1), transparent) !important;
  box-shadow: 0 0 18px rgba(245,212,0,0.9) !important;
  animation: v3xScanMove 0.5s linear infinite !important;
}

/* 顶部条 + 中央提示 */
body.forked .v3x-topbar__led {
  background: #f5d400; box-shadow: 0 0 0 2px #000, 0 0 18px #f5d400;
}

.v3x-fork-hint {
  position: fixed; top: 18%; left: 50%;
  transform: translateX(-50%); z-index: 11;
  text-align: center; opacity: 0;
  pointer-events: none;
  transition: opacity 0.4s, transform 0.4s;
}
body.forked .v3x-fork-hint { opacity: 1; }
.v3x-fork-hint .pre {
  font-family: 'Courier New', monospace;
  font-size: 11px; font-weight: 700;
  letter-spacing: 5px; color: #f5d400;
  text-transform: uppercase; margin-bottom: 6px;
  border-top: 1px solid #f5d400;
  border-bottom: 1px solid #f5d400;
  padding: 4px 0; display: inline-block;
}
.v3x-fork-hint .pre::before { content: "▌ "; }
.v3x-fork-hint .pre::after { content: " ▐"; }
.v3x-fork-hint .title {
  font-family: 'Courier New', monospace;
  font-size: 24px; font-weight: 900;
  letter-spacing: 10px; color: #fff;
  text-transform: uppercase; margin-top: 2px;
  text-shadow: 2px 2px 0 #f5d400, 4px 4px 0 rgba(214,0,0,0.55);
}
.v3x-fork-hint .sub {
  font-family: var(--font-kai);
  font-size: 13px; color: #d8d8d8;
  letter-spacing: 2px; font-style: italic;
  margin-top: 6px;
}
.v3x-fork-hint .sub::before { content: "· "; color: #f5d400; }
.v3x-fork-hint .sub::after { content: " ·"; color: #f5d400; }

/* ============ 右侧"样本已锁定"状态卡片 ============ */
.v3x-locked-state {
  display: block;
  margin-top: 10px; padding: 12px 14px 10px;
  background: rgba(0,0,0,0.6); border: 2px solid #f5d400;
  box-shadow: 3px 3px 0 #00ff66; text-align: left;
}
body.forked .v3x-action__btn { display: none; }
body:not(.forked) .v3x-locked-state { display: none; }
.v3x-locked-state__title {
  font-family: 'Courier New', monospace;
  font-weight: 900; font-size: 14px;
  color: #f5d400; letter-spacing: 3px;
  text-transform: uppercase; margin-bottom: 4px;
}
.v3x-locked-state__sub {
  font-family: 'Courier New', monospace;
  font-size: 11px; color: #fff; letter-spacing: 1.5px;
}
.v3x-locked-state__bar {
  margin-top: 7px; height: 4px; background: #222; overflow: hidden;
}
.v3x-locked-state__bar-fill {
  height: 100%; width: 100%;
  background: linear-gradient(90deg, #f5d400, #00ff66);
  animation: lockedBar 1.4s linear infinite;
}
@keyframes lockedBar {
  0% { transform: translateX(-100%); }
  100% { transform: translateX(100%); }
}

/* ================ 底部三分支 ================ */
.v3x-fork {
  position: fixed; left: 50%; bottom: 5%;
  transform: translateX(-50%) translateY(20px);
  z-index: 20; width: min(1200px, 96vw);
  opacity: 0; pointer-events: none;
  transition: opacity 0.4s, transform 0.4s;
}
body.forked .v3x-fork {
  opacity: 1; transform: translateX(-50%) translateY(0);
  pointer-events: auto;
}
.v3x-fork .row {
  display: grid; grid-template-columns: repeat(3, 1fr);
  gap: 26px;
}
.v3x-fork .foot {
  text-align: center; margin-top: 14px;
  font-family: var(--font-kai);
  font-size: 12.5px; color: #d8d8d8;
  letter-spacing: 1.5px; font-style: italic;
}
.v3x-fork .foot::before { content: "※ "; color: #f5d400; }
.v3x-fork .foot::after { content: " ※"; color: #f5d400; }

/* 通用 hover/selected · routing-to 标签 */
.v3x-fork .path-ancient,
.v3x-fork .path-modern,
.v3x-fork .path-western {
  position: relative;
  display: flex; flex-direction: column;
  cursor: pointer; text-decoration: none;
  transition: transform 0.2s, box-shadow 0.2s, border-color 0.2s;
  overflow: hidden; min-height: 220px;
}
.v3x-fork .path-ancient .routing-to,
.v3x-fork .path-modern .routing-to,
.v3x-fork .path-western .routing-to {
  position: absolute; bottom: 100%; left: 0; right: 0;
  text-align: center; padding: 7px 0;
  font-family: 'Courier New', monospace;
  font-weight: 900; font-size: 12px;
  letter-spacing: 3px; opacity: 0;
  transform: translateY(8px);
  transition: opacity 0.2s, transform 0.2s;
  pointer-events: none;
}
.v3x-fork .path-ancient:hover .routing-to,
.v3x-fork .path-modern:hover .routing-to,
.v3x-fork .path-western:hover .routing-to {
  opacity: 1; transform: translateY(0);
}

/* ==================== ① 古代 · 相书签牌 / 卷宗索引卡 v7 · 真实公版素材 ==================== */
.v3x-fork .path-ancient {
  color: #2a1f17;
  background-color: #f1e3b6;
  /* ★ 加入真实公版素材局部（1817 木刻相书 + 色诊图）作为底层纹理 */
  background-image:
    /* 上层左侧：色诊图局部（中医面部反射区划） */
    url('img/ancient-chinese-complexion-diagnosis.jpg'),
    /* 下层整张：木刻相书局部作为底纹 */
    url('img/ancient-chinese-physiognomy-diagnosis-1817.jpg'),
    /* 极淡横纹 */
    repeating-linear-gradient(0deg, rgba(74,58,42,0.06) 0 1px, transparent 1px 7px);
  background-repeat: no-repeat, no-repeat, repeat;
  background-size: 40% auto, 280px auto, auto;
  background-position: 0 100%, 100% 110%, 0 0;
  border: 2.5px solid #5e4a36;
  box-shadow: 4px 4px 0 #5e4a36;
  padding: 0;
  overflow: hidden;
}
.v3x-fork .path-ancient::before {
  content: ""; position: absolute; inset: 6px;
  border: 1px solid rgba(94,74,54,0.55); pointer-events: none;
}
.v3x-fork .path-ancient:hover {
  transform: translateY(-4px); border-color: #8a0d0d;
  box-shadow: 6px 6px 0 #8a0d0d, 0 0 30px rgba(138,13,13,0.35);
}
.v3x-fork .path-ancient .routing-to { background: #2a0d0d; color: #f1c4c4; }
.v3x-fork .path-ancient .header {
  display: flex; justify-content: space-between; align-items: flex-start;
  padding: 10px 14px 6px;
  border-bottom: 1px dashed rgba(94,74,54,0.4);
}
.v3x-fork .path-ancient .num {
  font-family: var(--font-mono);
  font-size: 12px; letter-spacing: 1.5px;
  color: #6a5944; padding-top: 2px;
}
.v3x-fork .path-ancient .num strong { color: #8a0d0d; font-size: 15px; }
.v3x-fork .path-ancient .seal {
  width: 48px; height: 48px;
  border: 2.5px solid #8a0d0d; color: #8a0d0d;
  font-family: var(--font-li); font-weight: 700; font-size: 11px;
  display: grid; grid-template-columns: 1fr 1fr; grid-template-rows: 1fr 1fr;
  transform: rotate(-6deg);
  background: rgba(255,248,225,0.45); line-height: 1;
}
.v3x-fork .path-ancient .seal span {
  display: flex; align-items: center; justify-content: center;
  border-right: 2px solid #8a0d0d; border-bottom: 2px solid #8a0d0d;
}
.v3x-fork .path-ancient .seal span:nth-child(2n) { border-right: none; }
.v3x-fork .path-ancient .seal span:nth-child(n+3) { border-bottom: none; }
.v3x-fork .path-ancient .nav-sign {
  display: flex; padding: 0 14px;
  background: rgba(94,74,54,0.1);
  border-bottom: 1px solid rgba(94,74,54,0.5);
}
.v3x-fork .path-ancient .nav-sign span {
  flex: 1; height: 7px; border-right: 1px solid rgba(94,74,54,0.4);
}
.v3x-fork .path-ancient .nav-sign span:last-child { border-right: none; }
.v3x-fork .path-ancient .body { padding: 14px 16px; flex: 1; }

/* ★ 古代真实素材 · 古籍相书局部裁切 · 显示在右下方 */
.v3x-fork .path-ancient .ancient-artifact {
  position: absolute;
  bottom: 38px;       /* 让按钮在它下方覆盖 */
  right: 14px;
  width: 110px;
  height: 90px;
  object-fit: cover;
  object-position: 60% 30%;   /* 裁切局部（人脸 + 宫位标记） */
  filter: sepia(0.55) saturate(0.5) brightness(0.95) contrast(1.05);
  opacity: 0.42;
  border: 1.5px solid #8a0d0d;
  box-shadow: 2px 2px 0 rgba(94,74,54,0.6);
  pointer-events: none;
  z-index: 0;
}
/* 古代 body 内的文字相对提升 */
.v3x-fork .path-ancient .body > * { position: relative; z-index: 2; }
.v3x-fork .path-ancient .name {
  font-family: var(--font-li); font-size: 30px; font-weight: 700;
  letter-spacing: 8px; color: #2a1f17;
  line-height: 1.1; margin-bottom: 4px;
}
.v3x-fork .path-ancient .sub {
  font-family: var(--font-kai); font-size: 14px;
  letter-spacing: 5px; color: #4a3a2a; margin-bottom: 10px;
}
.v3x-fork .path-ancient .divider {
  height: 1px; background: rgba(138,13,13,0.6);
  margin: 8px 0; position: relative;
}
.v3x-fork .path-ancient .divider::after {
  content: "朱砂批"; position: absolute; top: -7px; right: 0;
  background: rgba(241,227,182,1); padding: 0 6px;
  font-family: var(--font-kai); font-size: 10px;
  color: #8a0d0d; letter-spacing: 2px; font-weight: 700;
}
.v3x-fork .path-ancient .seal-line {
  font-family: var(--font-kai); font-size: 11px;
  color: #8a0d0d; letter-spacing: 2px;
  margin-bottom: 10px; font-weight: 700;
}
.v3x-fork .path-ancient .keys {
  display: flex; flex-wrap: wrap; gap: 6px;
  padding: 10px 14px;
  background: rgba(255,248,225,0.6);
  border-top: 1px dashed rgba(138,13,13,0.5);
}
.v3x-fork .path-ancient .keys span {
  font-family: var(--font-kai); font-size: 13px;
  padding: 3px 8px; background: rgba(255,248,225,1);
  border: 1px solid #8a0d0d; color: #2a1f17;
  letter-spacing: 2px; font-weight: 700;
}
.v3x-fork .path-ancient .action {
  padding: 14px 16px; border-top: 1px solid #5e4a36;
  text-align: right; background: rgba(94,74,54,0.18);
}
.v3x-fork .path-ancient .enter {
  display: inline-block; font-family: var(--font-mono);
  font-weight: 700; font-size: 14px;
  letter-spacing: 5px; color: #8a0d0d;
  text-transform: uppercase;
  padding: 7px 14px;
  border: 1.5px solid #8a0d0d;
  background: rgba(255,248,225,0.8);
}
.v3x-fork .path-ancient .enter::after { content: " ⇢"; }

/* ==================== ② 现代 · 身份清仓标签机 v7 · 半真实：摄像头抓拍 + 系统识别条 ==================== */
.v3x-fork .path-modern {
  color: #1a1a1a;
  background-color: #f5ecd0;
  background-image: repeating-linear-gradient(0deg, rgba(0,0,0,0.05) 0 1px, transparent 1px 5px);
  border: 4px solid #1a1a1a;
  box-shadow: 7px 7px 0 #d60000;
  padding: 0;
  overflow: hidden;
}
.v3x-fork .path-modern:hover {
  transform: translateY(-4px); border-color: #d60000;
  box-shadow: 10px 10px 0 #d60000, 0 0 30px rgba(214,0,0,0.4);
}
.v3x-fork .path-modern .routing-to { background: #1a1a1a; color: #f5d400; }
.v3x-fork .path-modern .header {
  display: flex; justify-content: space-between; align-items: center;
  padding: 8px 14px 7px; border-bottom: 2px solid #1a1a1a;
  background: #1a1a1a; color: #f5d400;
}
.v3x-fork .path-modern .num {
  font-family: 'Courier New', monospace; font-weight: 900;
  font-size: 12px; letter-spacing: 1.5px; color: #f5d400;
}
.v3x-fork .path-modern .num strong { font-size: 15px; color: #f5d400; }
.v3x-fork .path-modern .sku-chip {
  background: #d60000; color: #fff;
  font-family: 'Courier New', monospace; font-weight: 900;
  font-size: 12px; padding: 3px 9px;
  border: 2px solid #1a1a1a; letter-spacing: 1.4px;
}
.v3x-fork .path-modern .barcode {
  padding: 6px 14px; background: #fff;
  border-bottom: 2px solid #1a1a1a;
  font-family: 'Courier New', monospace; font-size: 13px;
  color: #1a1a1a; letter-spacing: 2px;
}
/* ★ 现代真实素材 · 多层身份识别结果（v8 完全重做） */
.v3x-fork .path-modern .modern-capture {
  background: #0a0a0e;
  background-image:
    repeating-linear-gradient(90deg, rgba(34,197,94,0.05) 0 1px, transparent 1px 18px);
  border-bottom: 2px solid #1a1a1a;
  padding: 8px 12px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  min-height: 78px;
}
/* 左侧：摄像头缩略 + 标签 */
.v3x-fork .path-modern .mod-side-left {
  display: flex;
  align-items: center;
  gap: 8px;
}
.v3x-fork .path-modern .cam-frame {
  background: #000;
  border: 1.5px solid #22c55e;
  width: 90px; height: 50px;
  flex-shrink: 0;
  overflow: hidden;
  position: relative;
  box-shadow: 0 0 8px rgba(34,197,94,0.4) inset, 0 0 4px rgba(34,197,94,0.6);
}
.v3x-fork .path-modern .cam-frame svg {
  width: 100%; height: 100%; display: block;
}
.v3x-fork .path-modern .cam-label {
  color: #22c55e;
  font-family: 'Courier New', monospace;
  font-weight: 900; font-size: 9px;
  letter-spacing: 1px;
  text-transform: uppercase;
}
/* 右侧：AI-LIVE · 系统识别粘纸（多行） */
.v3x-fork .path-modern .mod-side-right {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 4px;
}
.v3x-fork .path-modern .ai-tag {
  color: #22c55e;
  font-family: 'Courier New', monospace;
  font-weight: 900; font-size: 12px;
  letter-spacing: 1.5px;
  padding: 4px 8px;
  border: 1.5px solid #22c55e;
  background: rgba(34,197,94,0.12);
  text-transform: uppercase;
}
.v3x-fork .path-modern .ai-spec {
  color: #f5d400;
  font-family: 'Courier New', monospace;
  font-weight: 900; font-size: 10px;
  letter-spacing: 1.5px;
  background: rgba(214,0,0,0.85);
  border: 1.2px solid #d60000;
  padding: 2px 6px;
  text-transform: uppercase;
}
.v3x-fork .path-modern .ai-meta {
  color: #1a1a1a;
  font-family: 'Courier New', monospace;
  font-weight: 700; font-size: 9px;
  letter-spacing: 0.8px;
  background: #fff;
  padding: 1.5px 5px;
  border: 1px solid #1a1a1a;
}
/* ★ 像素化人脸预览条（8 个色块模拟"模糊像素头像"） */
.v3x-fork .path-modern .mod-pixel-face {
  background: #f5ecd0;
  border-bottom: 2px solid #1a1a1a;
  padding: 6px 12px;
}
.v3x-fork .path-modern .mod-pixel-row {
  display: grid;
  grid-template-columns: repeat(8, 1fr);
  gap: 2px;
  height: 14px;
}
.v3x-fork .path-modern .px {
  background: #1a1a1a;
  height: 100%;
}
/* 让中间 4 个像素块更亮（模拟"人脸轮廓"） */
.v3x-fork .path-modern .px:nth-child(3) { background: #d4a878; }
.v3x-fork .path-modern .px:nth-child(4) { background: #d4a878; }
.v3x-fork .path-modern .px:nth-child(5) { background: #d4a878; }
.v3x-fork .path-modern .px:nth-child(6) { background: #d4a878; }
.v3x-fork .path-modern .body { padding: 14px 16px; flex: 1; }
.v3x-fork .path-modern .name {
  font-family: 'Impact', 'Arial Black', sans-serif; font-size: 36px;
  font-weight: 900; letter-spacing: 2px; text-transform: uppercase;
  color: #1a1a1a;
  text-shadow: 3px 3px 0 #f5d400, 6px 6px 0 #1a1a1a;
  line-height: 1; margin: 0 0 6px;
}
.v3x-fork .path-modern .sub {
  font-family: 'Impact', 'Arial Black', sans-serif; font-size: 15px;
  font-weight: 900; letter-spacing: 3px; text-transform: uppercase;
  color: #1a1a1a; margin-bottom: 12px;
}
.v3x-fork .path-modern .sku-strip {
  display: flex; height: 12px; margin-bottom: 12px;
  border: 2px solid #1a1a1a;
}
.v3x-fork .path-modern .sku-strip span { flex: 1; border-right: 1px solid #1a1a1a; }
.v3x-fork .path-modern .sku-strip span:last-child { border-right: none; }
.v3x-fork .path-modern .sku-strip .s1 { background: #fde047; }
.v3x-fork .path-modern .sku-strip .s2 { background: #22d3ee; }
.v3x-fork .path-modern .sku-strip .s3 { background: #22c55e; }
.v3x-fork .path-modern .sku-strip .s4 { background: #fde047; }
.v3x-fork .path-modern .sku-strip .s5 { background: #f9a8d4; }
.v3x-fork .path-modern .sku-strip .s6 { background: #fef3c7; }
.v3x-fork .path-modern .tags-row { display: flex; gap: 5px; }
.v3x-fork .path-modern .tags-row span {
  flex: 1; text-align: center;
  font-family: 'Courier New', monospace; font-weight: 900;
